before.content:
    AgentRun run = acceptance.run().orElseThrow(() -> new IllegalStateException("prompt already accepted"));
    respond(id, Map.of());
    notifyUpdate(sessionId, codec.stateUpdate(sessionId, new AcpV2PreviewModel.StateUpdate.Running()).get("update"));
    run.completion().whenComplete((result, failure) -> {
        String stop = result != null && result.outcome() == AgentEvent.Outcome.ABORTED ? "cancelled" : "end_turn";
        notifyUpdate(sessionId, codec.stateUpdate(sessionId,
                new AcpV2PreviewModel.StateUpdate.Idle(java.util.Optional.of(stop))).get("update"));
    });
}

private void replay(String sessionId) {

after.content:
    subscribe(sessionId);
    String commandId = params.path("_meta").path("commandId").asText("acp-v2-" + java.util.UUID.randomUUID());
    PromptApplicationService.Acceptance acceptance = prompts.prompt(sessionId, commandId, text);
    acceptance.run().orElseThrow(() -> new IllegalStateException("prompt already accepted"));
    respond(id, Map.of());
    notifyUpdate(sessionId, codec.stateUpdate(sessionId, new AcpV2PreviewModel.StateUpdate.Running()).get("update"));
}
